    s:{ n:'∠ זווית', t:'סימן זווית (פולרי)', d:'במצב <b>CMPLX</b> – כתיבת מספר מרוכב בצורה <b>קוטבית</b>: r∠θ. למשל 2∠60.', only:'CMPLX', ex:[], tut:'t-cmplx' },
